# 1. CNIC 13-digit format validation
if doc.national_id_cnic:
    clean_cnic = "".join([c for c in doc.national_id_cnic if c.isdigit()])
    if len(clean_cnic) != 13:
        frappe.throw("Invalid CNIC! CNIC must consist of exactly 13 digits (XXXXX-XXXXXXX-X).")
    doc.national_id_cnic = f"{clean_cnic[:5]}-{clean_cnic[5:12]}-{clean_cnic[12:]}"

# 2. Freeze days calculation & expiry date extension
if doc.membership_status == "Frozen" and doc.freeze_start_date and doc.freeze_end_date:
    days = frappe.utils.date_diff(doc.freeze_end_date, doc.freeze_start_date)
    if days > 0 and not doc.flags.get("freeze_adjusted"):
        if doc.membership_expiry_date:
            doc.membership_expiry_date = frappe.utils.add_days(doc.membership_expiry_date, days)
        doc.freeze_days_consumed = (doc.freeze_days_consumed or 0) + days
        doc.flags.freeze_adjusted = True

# 3. Status handling based on expiry date
today = frappe.utils.today()
if doc.membership_status != "Frozen":
    if doc.membership_expiry_date and str(doc.membership_expiry_date) < str(today):
        doc.membership_status = "Expired"
    elif doc.membership_status != "Cancelled":
        doc.membership_status = "Active"

today_date = frappe.utils.today()

# 1. Jo members expire ho chuke hain aur Auto-Renew active hai unko aagay barhao
active_renewals = frappe.get_all("Gym Member", 
    filters={
        "membership_expiry_date": ["<", today_date],
        "membership_status": "Active",
        "auto_renew": 1
    },
    fields=["name", "membership_expiry_date"]
)

for member in active_renewals:
    next_expiry = frappe.utils.add_months(member.membership_expiry_date, 1)
    frappe.db.set_value("Gym Member", member.name, {
        "membership_expiry_date": next_expiry,
        "membership_status": "Active"
    })

# 2. Jo members expire ho chuke hain aur Auto-Renew band hai unko Expired mark karo
expired_members = frappe.get_all("Gym Member", 
    filters={
        "membership_expiry_date": ["<", today_date],
        "membership_status": "Active",
        "auto_renew": 0
    },
    fields=["name"]
)

for member in expired_members:
    frappe.db.set_value("Gym Member", member.name, "membership_status", "Expired")

frappe.db.commit()
